            State := 1;
        END_IF;
    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;
    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
        END_IF;
    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        IF NOT EStop AND Ticks(PT_REACT) >= 3 THEN
            State := 4;
        END_IF;
    4: -- Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

-- Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

