END_IF;

IF State = 1 OR State = 4 THEN
    DrainValve := FALSE;
ELSE
    DrainValve := FALSE;
END_IF;

IF State = 1 THEN
    FillValve := TRUE;
ELSE
    FillValve := FALSE;
END_IF;

IF State = 2 OR State = 3 THEN
    Heater := TRUE;
