CASE State OF
    0:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        StarTimer(IN := TRUE, PT := PT_STAR);
        IF NOT StarTimer.Q OR StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StarTimer.Q THEN
            State := 2;
        END_IF;
    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

