    State : INT := 0;
END_VAR

CASE State OF
    0: // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1: // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF T#3s <= PT_STAR THEN
            State := 2;
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

