END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;

    1: // Star
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF PT_STAR <= TON1.Q THEN
            State := 2;
        END_IF;
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        TON1(IN := TRUE, PT := PT_STAR);

    2: // Delta
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
END_CASE;

// Ensure star and delta cannot be on at the same time
IF StarK AND DeltaK THEN
