    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSIF NOT EStop AND StartCycle AND Level < 90 THEN
    State := 1;
ELSE
    CASE State OF
        0:
            IF StartCycle AND Level < 90 THEN
                State := 1;
            END_IF;
        1:
            IF Level >= 90 THEN
                State := 2;
            END_IF;
        2:
            IF Level <= 10 THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0:
        Pump := FALSE;
        Valve := FALSE;
    1:
        Pump := TRUE;
        Valve := FALSE;
    2:
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

