PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: -- Idle
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
            Pump := TRUE;
            Valve := FALSE;
        END_IF;

    1: -- Filling
        IF EStop OR Level >= 90 THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSIF Level <= 85 THEN
            Pump := TRUE;
            Valve := FALSE;
        ELSE
            Pump := FALSE;
            Valve := FALSE;
        END_IF;

    2: -- Draining
        IF EStop OR Level <= 10 THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSIF Level >= 15 THEN
            Pump := FALSE;
            Valve := TRUE;
        ELSE
            Pump := FALSE;
            Valve := FALSE;
        END_IF;
END_CASE

-- Safety conditions
ASSERT NOT (Pump AND Valve);
ASSERT Pump <= Level / 90;
ASSERT Valve >= Level / 10;

END_PROGRAM

