PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 2;
                C3 := TRUE;
            ELSE
                C3 := FALSE;
            END_IF;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 3;
                C2 := TRUE;
                C3 := TRUE;
            ELSE
                C2 := FALSE;
                C3 := FALSE;
            END_IF;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF StartPB AND State = 1 AND C3 AND NOT C2 THEN
    State := 2;
ELSIF StartPB AND State = 2 AND C3 AND C2 AND NOT C1 THEN
    State := 3;
END_IF;

CASE State OF
    0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
    1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
    2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
    3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
END_CASE;

END_PROGRAM

