PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND State = 0 THEN
    State := 1;
    C1 := FALSE;
    C2 := FALSE;
    C3 := TRUE;
ELSIF State = 1 AND NOT EStop AND NOT StopPB THEN
    IF State < 3 AND NOT EStop AND NOT StopPB THEN
        State := State + 1;
    END_IF;
    CASE State OF
        1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
        2: C1 := FALSE; C2 := TRUE;  C3 := TRUE;
        3: C1 := TRUE;  C2 := TRUE;  C3 := TRUE;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
