VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    SeqTimer1 : TON;
    SeqTimer2 : TON;
END_VAR

SeqTimer1(IN := NOT EStop AND StopPB OR State > 0, PT := T#2s);
SeqTimer2(IN := NOT EStop AND StopPB OR State > 1, PT := T#2s);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF NOT EStop AND StopPB THEN
            State := 0;
        ELSIF NOT EStop AND StartPB THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF NOT EStop AND StopPB THEN
            State := 0;
        ELSIF NOT EStop AND StartPB AND SeqTimer1.Q THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop AND StopPB THEN
            State := 0;
        ELSIF NOT EStop AND StartPB AND SeqTimer2.Q THEN
            State := 3;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF NOT EStop AND StopPB THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

