VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
END_IF;

CASE State OF
    0:
        IF StartPB AND NOT EStop AND NOT StopPB THEN
            State := 1;
        END_IF;
    1:
        IF TON1.Q AND NOT EStop AND NOT StopPB THEN
            State := 2;
        END_IF;
    2:
        IF TON2.Q AND NOT EStop AND NOT StopPB THEN
            State := 3;
        END_IF;
    3:
        IF NOT StartPB AND NOT EStop AND NOT StopPB THEN
            State := 3;
        END_IF;
END_CASE;

C1 := (State >= 3);
C2 := (State >= 2);
C3 := (State >= 1);

TON1(IN := TRUE, PT := PT_SEQ);
TON2(IN := TON1.Q, PT := PT_SEQ);

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
