VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T_C2 : TON;
    T_C1 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF T_C2.Q THEN
                State := 2;
            END_IF;
        2:
            IF T_C1.Q THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT StartPB THEN
                State := 0;
            END_IF;
    END_CASE;

    T_C2(IN := TRUE, PT := T#2s);
    T_C1(IN := TRUE, PT := T#2s);

    C3 := (State >= 1);
    C2 := (State >= 2);
    C1 := (State >= 3);
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;
END_PROGRAM

