            IF NOT StopPB THEN
                C1 := TRUE;
            END_IF;
    END_CASE;
    TON1(IN := (State >= 1), PT := PT_SEQ);
    TON2(IN := (State >= 2), PT := PT_SEQ);
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    State := 0;
END_IF;

