SeqTimer2(IN := NOT EStop AND NOT StopPB AND SeqTimer1.Q, PT := T#2s);

CASE State OF
    0: 
        C1 := FALSE; C2 := FALSE; C3 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1: 
        C1 := FALSE; C2 := FALSE; C3 := TRUE;
        IF SeqTimer1.Q THEN
            State := 2;
        END_IF;
    2: 
        C1 := FALSE; C2 := TRUE; C3 := TRUE;
        IF SeqTimer2.Q THEN
            State := 3;
        END_IF;
