PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND State = 0 THEN
    State := 1;
    C1 := FALSE;
    C2 := FALSE;
    C3 := TRUE;
ELSIF State = 1 AND T#2s.Q THEN
    State := 2;
    C1 := FALSE;
    C2 := TRUE;
    C3 := TRUE;
ELSIF State = 2 AND T#2s.Q THEN
    State := 3;
    C1 := TRUE;
    C2 := TRUE;
    C3 := TRUE;
ELSIF State > 0 AND NOT StartPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;

T#2s(IN := TRUE, PT := T#2s);

END_PROGRAM

